class MyDate extends Date { fmt(): string { return this.toISOString().slice(0, 10); } }
class MyRe extends RegExp { hit(s: string): boolean { return this.test(s); } }
function main(): void {
  const d = new MyDate(86400000);
  console.log(d.fmt(), d instanceof Date, d instanceof MyDate, d.getTime());
  const r = new MyRe('a+');
  console.log(r.hit('caat'), r.hit('zzz'), r instanceof RegExp, r.source);
}
